    if len(key) == 8:  # DES key is 8 bytes long
        cipher = DES.new(key, DES.MODE_ECB)
        return cipher.encrypt(data)
    elif len(key) == 16:  # AES key is 16 bytes long
        cipher = AES.new(key, AES.MODE_ECB)
        return cipher.encrypt(data)
    else:
        raise ValueError("Key must be either 8 bytes (for DES) or 16 bytes (for AES)")
