    '''
    Loads configuration from a YAML string.

    The function checks for the explicit '!!python' tag to prevent 
    object instantiation.
    '''
    try:
        document = yaml.load(config_data, Loader=yaml.FullLoader)
        # Check if there are any explicit!!python tags and handle them
        if isinstance(document, dict):
            for key, value in document.items():
                if isinstance(value, str) and value.startswith('!!python'):
